/**
 * Sword and Trowel
 * ----------------
 * The builders work with one hand and hold a sword in the other, and the work is done with the sound of the trumpet. Stage: a wall under construction at noon, a man with a trowel in one hand and a sword in the other, a trumpet on the wall; the work going on under arms.
 *
 * Palette 0x241810 → 0x060402 · light: dusk · hero: horn
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./nehemiah-kit.js.
 */

import { THREE, createScene, cityGate, house, army, horn, person, birds } from './nehemiah-kit.js';

const BG = 0x241810;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 3359909771, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [-8, 0, -58], { name: 'city', r: [0, 0.18, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0x060402, trim: 0x050302 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x060402 });
    }
    W.backdrop(city);

    /* army: shields and spears in rank */
    army(W, group, -10.5, 21.9, 11, { shields: [0x17100a, 0x050402, 0x8a7a2a, 0x3a5a8a] });

    /* hero: the horn */
    horn(W, group, 0, 1.2, 0, 1.3, { color: 0x20160e });
    W.disc([0, 4, -10], 4, 0x2f1f15, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x241810, ry: -0.67, s: 1.03 });
    person(W, group, [4.5, 0, 6], { robe: 0x060402, ry: -0.53, s: 1.00 });

    /* birds: slow circles high above */
    birds(W, group, 8, 55, { y: 26 });

    return W.finish();
}

export default { build };
